import"./shimless_rma_shared.css.js";import"./base_page.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{getShimlessRmaService}from"./mojo_interface_provider.js";import{getTemplate}from"./onboarding_choose_wp_disable_method_page.html.js";import{disableNextButton,enableNextButton,focusPageTitle}from"./shimless_rma_util.js";const OnboardingChooseWpDisableMethodPageBase=I18nMixin(PolymerElement);export class OnboardingChooseWpDisableMethodPage extends OnboardingChooseWpDisableMethodPageBase{constructor(){super(...arguments);this.shimlessRmaService=getShimlessRmaService()}static get is(){return"onboarding-choose-wp-disable-method-page"}static get template(){return getTemplate()}static get properties(){return{allButtonsDisabled:Boolean,hwwpMethod:{type:String,value:""}}}ready(){super.ready();focusPageTitle(this)}onHwwpDisableMethodSelectionChanged(event){this.hwwpMethod=event.detail.value;const disabled=!this.hwwpMethod;if(disabled){disableNextButton(this)}else{enableNextButton(this)}}onNextButtonClick(){if(this.hwwpMethod==="hwwpDisableMethodManual"){return this.shimlessRmaService.chooseManuallyDisableWriteProtect()}else if(this.hwwpMethod==="hwwpDisableMethodRsu"){return this.shimlessRmaService.chooseRsuDisableWriteProtect()}else{return Promise.reject(new Error("No disable method selected"))}}}customElements.define(OnboardingChooseWpDisableMethodPage.is,OnboardingChooseWpDisableMethodPage);